def crear_puntos_generales(apps, schema_editor):
    """Crea el punto General de cada sitio con su QR y su fecha de impresión.

    Los QR ya impresos siguen resolviendo: el punto hereda el ``qr_codigo``.
    """
    Sitio = apps.get_model("sitios", "Sitio")
    PuntoControl = apps.get_model("sitios", "PuntoControl")
    PuntoControl.objects.bulk_create(
        PuntoControl(
            sitio_id=sitio.pk,
            nombre="General",
            orden=0,
            activo=sitio.activo,
            qr_codigo=sitio.qr_codigo,
            qr_impreso_el=sitio.qr_impreso_el,
        )
        for sitio in Sitio.objects.all()
    )


def devolver_qr_al_sitio(apps, schema_editor):
    """Copia el QR del punto General de vuelta al sitio y descarta los puntos."""
    Sitio = apps.get_model("sitios", "Sitio")
    PuntoControl = apps.get_model("sitios", "PuntoControl")
    for punto in PuntoControl.objects.filter(orden=0).order_by("-id"):
        Sitio.objects.filter(pk=punto.sitio_id).update(
            qr_codigo=punto.qr_codigo, qr_impreso_el=punto.qr_impreso_el
        )
    PuntoControl.objects.all().delete()


